// WithDefaultAttributes returns a [metric.InstrumentOption] that specifies
// which attribute keys are allowed by default for a metric instrument.
//
// When the returned option is passed during instrument creation, only
// attributes whose keys appear in keys are included in the recorded data
// points; all other attributes are filtered out. Passing no keys results in
// all attributes being filtered out (an empty attribute set).
//
// If this option is not provided, no attribute filtering is applied and all
// recorded attributes are retained.
//
// The returned option is experimental. It is safe to pass to the standard
// metric API: the attribute filtering is only honored by SDK implementations
// that understand this option, and it is ignored by others.
func WithDefaultAttributes(keys ...attribute.Key) metric.InstrumentOption {
	// A nil slice signals "the option was not provided" to the SDK. Ensure a
	// non-nil (possibly empty) slice is stored so that passing no keys is
	// distinguishable from not passing the option at all.
	if keys == nil {
		keys = []attribute.Key{}
	}
	return defaultAttributesOption{keys: keys}
}

// defaultAttributesOption is a [metric.InstrumentOption] that restricts the
